def investigar_substantivo(palavra, frase):
    # Modelo didático de raciocínio, não um classificador infalível.
    if nomeia_ser_ou_conceito(palavra, frase):
        hipotese = 'substantivo'
        if tem_determinante(palavra, frase):
            # indício, não prova: o artigo também substantiva
            hipotese += ' (reforçado pelo determinante)'
        return hipotese
    if caracteriza_nome(palavra, frase):
        return 'investigar adjetivo'
    return 'analisar o contexto completo'

def investigar_adjetivo(palavra, frase):
    nome = substantivo_caracterizado(palavra, frase)
    if nome is not None:
        if concorda(palavra, nome):
            return f'adjetivo: caracteriza {nome}'
        return 'verificar: não há concordância, rever hipótese'
    if precedida_de_determinante(palavra, frase):
        return 'investigar emprego substantivado'
    if modifica_verbo(palavra, frase):
        return 'investigar advérbio'
    return 'analisar o contexto completo'

def investigar_expressao_preposicionada(expr, frase):
    alvo = termo_modificado(expr, frase)
    if eh_substantivo(alvo) and caracteriza(expr, alvo):
        return 'investigar locução adjetiva'
    if eh_verbo(alvo) and indica_circunstancia(expr):
        return 'investigar locução adverbial'
    if verbo_exige_preposicao(alvo):
        return 'investigar complemento verbal (regência)'
    return 'analisar o contexto completo'

def investigar_artigo(palavra, frase):
    if palavra.lower() not in {'o', 'a', 'os', 'as', 'um', 'uma', 'uns', 'umas'}:
        return 'não é forma de artigo'
    proxima = proxima_palavra(palavra, frase)
    if determina_nome(palavra, proxima):
        if palavra.lower() in {'um', 'uma'} and contexto_de_quantidade(frase):
            return 'investigar numeral'
        return 'artigo'
    if substitui_nome_junto_a_verbo(palavra, frase):
        return 'investigar pronome oblíquo'
    return 'investigar preposição'

def investigar_pronome(palavra, frase):
    if palavra.lower() in {'muito', 'pouco', 'bastante'}:
        if acompanha_substantivo(palavra, frase):
            return 'pronome indefinido adjetivo'
        return 'investigar advérbio de intensidade'
    if acompanha_substantivo(palavra, frase):
        return 'pronome adjetivo'
    if ocupa_lugar_de_nome(palavra, frase):
        return 'pronome substantivo'
    return 'analisar o contexto completo'

def investigar_numeral(palavra, frase):
    tipo = tipo_numerico(palavra)  # cardinal, ordinal, multiplicativo, fracionário ou None
    if tipo is None:
        if quantidade_vaga(palavra):
            return 'investigar pronome indefinido'
        return 'não é numeral'
    if acompanha_substantivo(palavra, frase):
        return f'numeral {tipo} adjetivo'
    return f'numeral {tipo} substantivo'
